@@ -40,6 +40,16 @@ export class Channel {
+  /** Limits how many times a failed publish is retried. */
+  setRetryLimit(limit: number): void {
+    if (limit < 0) {
+      throw new ErrorInfo('limit must be zero or more', { code: 40003 });
+    }
+    this.retryLimit = limit;
+  }
+
+  // Failures past the limit reject with a new error.
+  retryLimitExceeded = { errorCode: 49999, statusCode: 400 };
